#include "MusicCompanion.h"
#include <QJsonArray>
#include <QFile>
#include <QDateTime>
#include <QTimeZone>
#include <QRegularExpression>
#include <QSet>
#include <algorithm>

QVariantList MusicCompanion::searches() const{QVariantList list;QSet<QString> seen;for(auto v:m_data["searches"].toArray()){auto q=v.toString().trimmed().left(200);if(!q.isEmpty()&&!seen.contains(q.toCaseFolded())&&list.size()<20){seen.insert(q.toCaseFolded());list<<q;}}return list;}
void MusicCompanion::rememberSearch(const QString &raw){QString q=raw.trimmed().left(200);if(q.isEmpty())return;QJsonArray list;list.append(q);for(auto v:m_data["searches"].toArray())if(v.isString()&&v.toString().compare(q,Qt::CaseInsensitive)!=0&&list.size()<20)list.append(v);m_data["searches"]=list;save();}
void MusicCompanion::forgetSearch(const QString &query){QJsonArray list;for(auto v:m_data["searches"].toArray())if(!query.isEmpty()&&v.toString()!=query)list.append(v);m_data["searches"]=list;save();}
QVariantMap MusicCompanion::lyricStyle() const{QVariantMap s{{"lyricFont","Sans"},{"translationFont","Sans"},{"lyricColor","#F5F5F5"},{"translationColor","#CEE9F0"},{"lyricSize",26},{"translationSize",21}};auto saved=m_data["lyricStyle"].toObject();for(auto it=saved.begin();it!=saved.end();++it)if(s.contains(it.key())){if(it.key().endsWith("Font")&&QStringList{"Sans","Serif","Mono","Rounded"}.contains(it.value().toString()))s[it.key()]=it.value().toString();else if(it.key().endsWith("Color")&&QRegularExpression("^#[0-9a-fA-F]{6}$").match(it.value().toString()).hasMatch())s[it.key()]=it.value().toString();else if(it.key().endsWith("Size")&&it.value().isDouble())s[it.key()]=std::clamp(it.value().toInt(),16,44);}return s;}
void MusicCompanion::setLyricStyle(const QString &key,const QVariant &value){auto s=lyricStyle();if(!s.contains(key))return;if(key.endsWith("Font")&&!QStringList{"Sans","Serif","Mono","Rounded"}.contains(value.toString()))return;if(key.endsWith("Color")&&!QRegularExpression("^#[0-9a-fA-F]{6}$").match(value.toString()).hasMatch())return;s[key]=key.endsWith("Size")?QVariant(std::clamp(value.toInt(),16,44)):value;m_data["lyricStyle"]=QJsonObject::fromVariantMap(s);save();}
QVariantMap MusicCompanion::statistics(int days,const QString &dimension) const{
  days=std::clamp(days,1,180);const qint64 now=QDateTime::currentMSecsSinceEpoch(),cutoff=QDateTime(QDate::currentDate().addDays(1-days),QTime(0,0),QTimeZone::systemTimeZone()).toMSecsSinceEpoch();auto tracks=m_data["tracks"].toObject();QMap<QString,QVariantMap> groups;QSet<QString> heard,analyzed,artists,albums;QMap<QString,double> tones;double totalMs=0;int totalPlays=0,genreCount=0;
  for(auto value:m_data["events"].toArray()){
    auto e=value.toObject();double at=e["at"].toDouble();if(at<cutoff||at>now)continue;auto t=tracks[e["key"].toString()].toObject();if(t.isEmpty())continue;auto trackKey=e["key"].toString();const auto artist=t["artist"].toString(),album=t["album"].toString();QString label=dimension=="artists"?artist:dimension=="albums"?album:dimension=="genres"?t["genre"].toString():dimension=="days"?QDateTime::fromMSecsSinceEpoch(qint64(at)).date().toString("yyyy-MM-dd"):t["title"].toString();if(label.isEmpty())label="Não informado";
    QString id=dimension=="tracks"?trackKey:dimension=="albums"?artist+"|"+label:label;auto r=groups.value(id,QVariantMap{{"id",id},{"label",label},{"ms",0.},{"plays",0},{"tracks",QVariantList{}},{"trackTotals",QVariantMap{}},{"albumTotals",QVariantMap{}}});double ms=std::clamp(e["ms"].toDouble(),0.,86400000.);const int play=e["play"].toBool()?1:0;r["ms"]=r["ms"].toDouble()+ms;r["plays"]=r["plays"].toInt()+play;auto totals=r["trackTotals"].toMap();auto tr=totals.value(trackKey,t.toVariantMap()).toMap();tr["listenedMs"]=tr.value("listenedMs").toDouble()+ms;tr["listenedPlays"]=tr.value("listenedPlays").toInt()+play;totals[trackKey]=tr;r["trackTotals"]=totals;auto albumTotals=r["albumTotals"].toMap();QString albumKey=artist+"|"+album;auto ar=albumTotals[albumKey].toMap();ar["album"]=album.isEmpty()?"Álbum não informado":album;ar["artist"]=artist;ar["ms"]=ar["ms"].toDouble()+ms;ar["plays"]=ar["plays"].toInt()+play;auto ids=ar["trackIds"].toStringList();if(!ids.contains(trackKey))ids<<trackKey;ar["trackIds"]=ids;ar["trackCount"]=ids.size();albumTotals[albumKey]=ar;r["albumTotals"]=albumTotals;groups[id]=r;
    totalMs+=ms;totalPlays+=play;heard.insert(trackKey);if(!artist.isEmpty())artists.insert(artist);if(!album.isEmpty())albums.insert(albumKey);if(t["lyricsAnalyzed"].toBool())analyzed.insert(trackKey);if(!t["genre"].toString().isEmpty())genreCount++;auto profile=t["tone"].toObject();if(profile.isEmpty())profile=QJsonObject::fromVariantMap(tone({},t["genre"].toString()));for(auto it=profile.begin();it!=profile.end();++it)tones[it.key()]+=it.value().toDouble()*ms;
  }
  QVariantList rows;for(auto r:groups){QVariantList entries,albumRows;auto totals=r.take("trackTotals").toMap();for(auto v:totals)entries<<v;auto als=r.take("albumTotals").toMap();for(auto v:als)albumRows<<v;std::stable_sort(entries.begin(),entries.end(),[](auto a,auto b){return a.toMap()["listenedMs"].toDouble()>b.toMap()["listenedMs"].toDouble();});r["tracks"]=entries;r["albums"]=albumRows;r["trackCount"]=entries.size();r["albumCount"]=albumRows.size();rows<<r;}if(dimension!="days")std::stable_sort(rows.begin(),rows.end(),[](auto a,auto b){return a.toMap()["ms"].toDouble()>b.toMap()["ms"].toDouble();});if(rows.size()>30)rows=rows.mid(0,30);
  QString dominant;double best=0;for(auto it=tones.begin();it!=tones.end();++it)if(it.value()>best){best=it.value();dominant=it.key();}QString vibe=totalPlays>=3&&!analyzed.isEmpty()&&!dominant.isEmpty()?"Clima "+dominant:"Dados insuficientes";
  QVariantList suggestions;QSet<QString> known;QString genres;for(auto h:heard){auto t=tracks[h].toObject();known.insert(t["artist"].toString().toCaseFolded());genres+=" "+t["genre"].toString().toCaseFolded();}QFile f(":/companion/resources/music-rules.json");f.open(QIODevice::ReadOnly);auto rules=QJsonDocument::fromJson(f.readAll()).object();for(auto v:rules["recommendations"].toArray()){auto rule=v.toObject();bool match=false;for(auto g:rule["genres"].toArray())if(genres.contains(g.toString().toCaseFolded()))match=true;if(match)for(auto a:rule["artists"].toArray())if(!known.contains(a.toString().toCaseFolded())&&!suggestions.contains(a.toString()))suggestions<<a.toString();}
  return {{"rows",rows},{"ms",totalMs},{"plays",totalPlays},{"vibe",vibe},{"coverage",heard.size()},{"lyricCoverage",analyzed.size()},{"artistCount",artists.size()},{"albumCount",albums.size()},{"recommendations",suggestions.mid(0,12)},{"explanation",QString("%1 escutas • %2 músicas • %3 artistas • %4 álbuns. Letras analisadas: %5/%2; estilos em %6 sessões. Leitura do repertório, sem diagnóstico pessoal.").arg(totalPlays).arg(heard.size()).arg(artists.size()).arg(albums.size()).arg(analyzed.size()).arg(genreCount)}};
}
QVariantMap MusicCompanion::insights(int days) const{
  auto report=statistics(days,"artists");report["artists"]=report["rows"];report["albums"]=statistics(days,"albums")["rows"];report["genres"]=statistics(days,"genres")["rows"];QMap<QString,double> sums;QSet<QString> coverage;double ms=0;auto tracks=m_data["tracks"].toObject();const qint64 now=QDateTime::currentMSecsSinceEpoch(),cutoff=QDateTime(QDate::currentDate().addDays(1-std::clamp(days,1,180)),QTime(0,0),QTimeZone::systemTimeZone()).toMSecsSinceEpoch();for(auto v:m_data["events"].toArray()){auto e=v.toObject();if(e["at"].toDouble()<cutoff||e["at"].toDouble()>now)continue;auto t=tracks[e["key"].toString()].toObject();auto topics=t["topics"].toObject();if(topics.isEmpty())continue;double duration=e["ms"].toDouble();ms+=duration;coverage.insert(e["key"].toString());for(auto it=topics.begin();it!=topics.end();++it)if(it.value().toDouble()>=.60)sums[it.key()]+=duration;}QVariantList themes;for(auto it=sums.begin();it!=sums.end();++it)themes<<QVariantMap{{"label",it.key()},{"percent",ms>0?100*it.value()/ms:0}};std::stable_sort(themes.begin(),themes.end(),[](auto a,auto b){return a.toMap()["percent"].toDouble()>b.toMap()["percent"].toDouble();});report["themes"]=themes;report["modelCoverage"]=coverage.size();report["model"]="TonalMuse Tiny v1 • classificador local C++ • 32 KiB de pesos";return report;
}
